#!/usr/bin/env python3
# Blackout-Radar Schritt 7: Reserve einmal pro Woche nachfuellen.
# Kein Mesh, keine Abschaltung. Pinneberg bleibt pausiert.
from __future__ import annotations
import base64, hashlib, os, shutil, sys
from datetime import datetime
from pathlib import Path

DASH = Path("/home/fmg/prepper-dashboard")
PATCH = ("blackout_radar.py",)
CHECK = ("dashboard.py", "lage_pages.py", "pushover_push.py")
PI = {
    "dashboard.py": ("239bdf4d0f761325", 1392013),
    "blackout_radar.py": ("7a363f4723032c15", 74404),
    "lage_pages.py": ("e9ea014b5a4ff121", 230936),
    "pushover_push.py": ("2267a556ab7bb27f", 12129),
}

def load():
    raw = PAYLOAD_JSON
    return {name: [(base64.b64decode(x["old"]), base64.b64decode(x["new"])) for x in raw["pairs"][name]] for name in PATCH}

def sha(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()

def fenster(now=None):
    from zoneinfo import ZoneInfo
    jetzt = now or datetime.now(ZoneInfo("Europe/Berlin"))
    m = jetzt.minute
    return (not (m >= 45 or m <= 4)), "Berlin Minute %02d" % m

def verwandle(data, pairs):
    if all(data.count(neu) == 1 and data.count(old) == 0 for old, neu in pairs):
        return data
    neu_data = data
    for old, neu in pairs:
        if neu_data.count(neu) == 1 and neu_data.count(old) == 0:
            continue
        if neu_data.count(old) != 1 or neu_data.count(neu) != 0:
            raise RuntimeError("Stelle")
        vor = neu_data
        neu_data = neu_data.replace(old, neu, 1)
        if neu_data.replace(neu, b"", 1) != vor.replace(old, b"", 1):
            raise RuntimeError("ausserhalb")
    return neu_data

def sichern(path: Path, data: bytes):
    stempel = datetime.now().astimezone().strftime("%Y%m%dT%H%M%S")
    alt = sorted(path.parent.glob(path.name + ".bak-bor7-*"))
    bak = path.with_name(path.name + ".bak-bor7-" + stempel)
    shutil.copy2(path, bak)
    if bak.read_bytes() != data:
        bak.unlink()
        raise RuntimeError("Sicherung weicht ab")
    for alt_pfad in alt[:-2]:
        try:
            alt_pfad.unlink()
        except OSError:
            pass

def schreiben(path: Path, data: bytes):
    mode = path.stat().st_mode & 0o777
    tmp = path.with_name("." + path.name + ".tmp-bor7")
    if tmp.exists():
        raise RuntimeError("temporaere Datei existiert")
    try:
        with open(tmp, "wb") as handle:
            handle.write(data)
            handle.flush()
            os.fsync(handle.fileno())
        os.chmod(tmp, mode)
        os.replace(tmp, path)
    finally:
        if tmp.exists():
            try:
                tmp.unlink()
            except OSError:
                pass

def apply_dir(ordner: Path, dry: bool, kein: bool, jetzt=None) -> int:
    paare = load()
    falsch = False
    blobs = {}
    for name in list(PATCH) + list(CHECK):
        pfad = ordner / name
        if pfad.is_symlink() or not pfad.is_file():
            print("STOP: %s fehlt" % name)
            return 2
        data = pfad.read_bytes()
        blobs[name] = data
        kopf, laenge = PI[name]
        ist = sha(data)
        print("%s sha16 %s bytes %d" % (name, ist[:16], len(data)))
        if not ist.startswith(kopf) or len(data) != laenge:
            print("STOP: %s %s ist nicht die Basis" % (name, ist[:16]))
            falsch = True
    if falsch:
        return 2
    try:
        ziel = {name: verwandle(blobs[name], paare[name]) for name in PATCH}
    except RuntimeError:
        print("STOP: Stelle unbekannt")
        return 2
    compile(ziel["blackout_radar.py"], "blackout_radar.py", "exec")
    if b"RESERVE_WOCHE" not in ziel["blackout_radar.py"] or b"reserve_refresh_last" not in ziel["blackout_radar.py"]:
        print("STOP: Reserve-Nachfuellen fehlt")
        return 2
    print("blackout_radar.py endstand sha16 %s bytes %d" % (sha(ziel["blackout_radar.py"])[:16], len(ziel["blackout_radar.py"])))
    for name in CHECK:
        print("%s endstand sha16 %s bytes %d" % (name, sha(blobs[name])[:16], len(blobs[name])))
    frei, meldung = fenster(jetzt)
    print(meldung)
    if blobs["blackout_radar.py"] == ziel["blackout_radar.py"]:
        print("bereits installiert, keine Aenderung, kein Neustart")
        return 0
    if dry:
        print("DRY-RUN: kein Backup, kein Schreiben, kein Neustart")
        print("Pruefung: curl -sS http://127.0.0.1:5000/api/blackout/radar")
        return 0
    if not frei:
        print("STOP: Neustart-Sperre Minute 45-59 und 00-04 Berlin. Nichts geschrieben.")
        return 2
    try:
        sichern(ordner / "blackout_radar.py", blobs["blackout_radar.py"])
        schreiben(ordner / "blackout_radar.py", ziel["blackout_radar.py"])
    except (OSError, RuntimeError) as exc:
        print("STOP beim Schreiben: %s" % exc)
        return 3
    print("geschrieben. Reserve einmal pro Woche, Tausch nach 21 Tagen.")
    if kein:
        print("Kein Neustart in dieser Pruefung.")
        return 0
    frei, meldung = fenster()
    print(meldung)
    if not frei:
        print("STOP: Datei ist neu, der Neustart bleibt in der Sperre aus.")
        return 2
    __import__("subprocess").run(["systemctl", "restart", "prepper-dashboard.service"], check=False)
    print("Nur prepper-dashboard neu gestartet.")
    return 0

def selftest() -> int:
    assert fenster(datetime(2026, 11, 13, 12, 12))[0]
    assert not fenster(datetime(2026, 11, 13, 12, 45))[0]
    assert not fenster(datetime(2026, 11, 13, 12, 0))[0]
    paare = load()
    old, neu = paare["blackout_radar.py"][0]
    assert neu.count(old) == 0
    assert verwandle(b"VOR" + old + b"NACH", [(old, neu)]) == b"VOR" + neu + b"NACH"
    import tempfile
    ordner = Path(tempfile.mkdtemp(prefix="bor7-"))
    for name in list(PATCH) + list(CHECK):
        (ordner / name).write_bytes(b"UNBERUEHRT")
    vorher = {name: (ordner / name).read_bytes() for name in list(PATCH) + list(CHECK)}
    assert apply_dir(ordner, True, True, datetime(2026, 11, 13, 12, 12)) == 2
    assert vorher == {name: (ordner / name).read_bytes() for name in vorher}
    print("selftest ok")
    return 0

def main(argv):
    args = argv[1:]
    dry = kein = False
    wurzel = DASH
    i = 0
    while i < len(args):
        a = args[i]
        if a == "--dry-run":
            dry = True
        elif a == "--kein-neustart":
            kein = True
        elif a == "--selftest":
            return selftest()
        elif a == "--wurzel":
            i += 1
            wurzel = Path(args[i])
        else:
            print("STOP: unbekanntes Argument")
            return 2
        i += 1
    return apply_dir(wurzel, dry, kein)

PAYLOAD_JSON = {"pairs":{"blackout_radar.py":[{"old":"","new":""}]}}

if __name__ == "__main__":
    sys.exit(main(sys.argv))
